# ui.py: page helpers shared by final.py. Students do NOT edit this file.
import html, os

CSS = open(os.path.join(os.path.dirname(os.path.abspath(__file__)), "style.css"), encoding="utf-8").read()


def box(s):
    """Grey box for a step that is not done, red box for a step with an error."""
    if s["status"] == "error":
        return '<div class="error">🔴 Step %d (%s) has an error: %s</div>' % (s["n"], s["file"], html.escape(s["err"]))
    day = " · Day 3" if s["day"] == 3 else ""
    return '<div class="todo%s">⬜ <b>Step %d: %s</b>%s · not done yet · open <code>%s</code></div>' % (
        " d3" if s["day"] == 3 else "", s["n"], s["title"], day, s["file"])


def part(s, *args):
    """Run the student's function if the step is done, else show the grey box."""
    if s["status"] != "done":
        return box(s)
    try:
        return s["f"](*args)
    except Exception as e:
        return '<div class="error">🔴 Step %d: %s</div>' % (s["n"], html.escape("%s: %s" % (type(e).__name__, e)))


def page(app, S, inner):
    total = len(S)
    done = sum(1 for s in S.values() if s["status"] == "done")
    chips = "".join('<span class="%s">%s %d</span>' % (
        "ok" if s["status"] == "done" else ("err" if s["status"] == "error" else ""),
        "✅" if s["status"] == "done" else ("🔴" if s["status"] == "error" else "⬜"), s["n"]) for s in S.values())
    return """<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>%s</title><style>%s</style></head><body><div class="wrap">
<div class="top"><div><b>ILP WORKSHOP</b><div>%s</div></div>
<div class="prog"><small>%d / %d steps done</small><div class="bar"><i style="width:%d%%"></i></div></div></div>
<div class="steps">%s</div>
%s
</div></body></html>""" % (app, CSS, app, done, total, round(done * 100 / total), chips, inner)
